// Generates placeholder product photos as SVG data URIs, one per colour and view.
// They stand in for real photography of the shoe.

const SOLE = '#2b2c2f'
const LIGHT = '#f2f2f0'

function shoeSvg(colorHex, view) {
  const upper = colorHex
  const accent = '#ffffff'
  let body = ''

  if (view === 'side') {
    body = `
      <ellipse cx="310" cy="338" rx="220" ry="14" fill="#000" opacity="0.12"/>
      <path d="M120 292 L120 200 Q120 150 170 145 L250 150 Q275 190 330 200 Q420 210 480 240 Q520 255 505 296 Z" fill="${upper}"/>
      <path d="M120 200 Q200 216 330 226" stroke="${accent}" stroke-width="6" fill="none" opacity="0.5"/>
      <path d="M250 168 L282 178 M262 190 L294 200 M276 212 L308 222" stroke="${accent}" stroke-width="5" stroke-linecap="round" opacity="0.8"/>
      <path d="M104 292 L502 288 Q528 296 508 332 L120 334 Q96 322 104 292 Z" fill="${SOLE}"/>`
  } else if (view === 'front') {
    body = `
      <ellipse cx="300" cy="352" rx="150" ry="12" fill="#000" opacity="0.12"/>
      <path d="M190 90 Q300 60 410 90 Q440 200 430 300 Q300 330 175 300 Q160 200 190 90 Z" fill="${upper}"/>
      <path d="M200 110 Q300 88 400 110" stroke="${accent}" stroke-width="5" fill="none" opacity="0.5"/>
      <path d="M235 140 L365 140 M240 165 L360 165 M245 190 L355 190" stroke="${accent}" stroke-width="5" stroke-linecap="round" opacity="0.8"/>
      <path d="M175 300 Q300 336 430 300 Q440 340 300 348 Q165 342 175 300 Z" fill="${SOLE}"/>`
  } else if (view === 'heel') {
    body = `
      <ellipse cx="300" cy="352" rx="110" ry="10" fill="#000" opacity="0.12"/>
      <path d="M220 60 Q300 40 380 60 Q402 200 386 320 Q300 346 214 320 Q198 200 220 60 Z" fill="${upper}"/>
      <ellipse cx="300" cy="72" rx="58" ry="14" fill="#111"/>
      <rect x="284" y="36" width="32" height="30" rx="5" fill="${accent}" opacity="0.85"/>
      <path d="M230 230 Q300 250 372 230" stroke="${accent}" stroke-width="5" fill="none" opacity="0.4"/>
      <path d="M214 320 Q300 350 386 320 Q392 340 300 352 Q208 344 214 320 Z" fill="${SOLE}"/>`
  } else {
    // Outsole, seen from below, with lugs.
    let lugs = ''
    for (let y = 80; y <= 320; y += 40) {
      for (let x = 230; x <= 370; x += 40) {
        lugs += `<circle cx="${x + ((y / 40) % 2) * 20}" cy="${y}" r="9" fill="#55585e"/>`
      }
    }
    body = `
      <path d="M200 40 Q300 20 400 60 Q430 200 400 340 Q300 370 200 340 Q170 200 200 40 Z" fill="${SOLE}"/>
      ${lugs}
      <path d="M200 40 Q300 20 400 60 Q430 200 400 340 Q300 370 200 340 Q170 200 200 40 Z" fill="none" stroke="${upper}" stroke-width="10"/>`
  }

  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 400">
    <rect width="600" height="400" fill="${LIGHT}"/>
    ${body}
  </svg>`
}

export function shoeImageSrc(colorHex, view) {
  return `data:image/svg+xml;charset=utf-8,${encodeURIComponent(shoeSvg(colorHex, view))}`
}
