import { useId, useRef } from 'react'

// APG radio group: arrow keys move and select, Tab leaves the group.
export default function ColorPicker({ colors, value, onChange }) {
  const labelId = useId()
  const refs = useRef([])
  const selected = colors.find((c) => c.id === value)

  function select(index) {
    onChange(colors[index].id)
    refs.current[index]?.focus()
  }

  function onKeyDown(e, index) {
    const last = colors.length - 1
    let next = null
    if (e.key === 'ArrowRight' || e.key === 'ArrowDown') next = index === last ? 0 : index + 1
    if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') next = index === 0 ? last : index - 1
    if (e.key === 'Home') next = 0
    if (e.key === 'End') next = last
    if (next !== null) {
      e.preventDefault()
      select(next)
    }
  }

  return (
    <div className="option-group">
      <p className="option-group__label" id={labelId}>
        Color: <span>{selected?.name}</span>
      </p>
      <div role="radiogroup" aria-labelledby={labelId} className="swatches">
        {colors.map((color, index) => {
          const checked = color.id === value
          return (
            <button
              key={color.id}
              ref={(el) => (refs.current[index] = el)}
              type="button"
              role="radio"
              aria-checked={checked}
              aria-label={color.name}
              tabIndex={checked ? 0 : -1}
              className="swatch"
              style={{ '--swatch': color.hex }}
              onClick={() => onChange(color.id)}
              onKeyDown={(e) => onKeyDown(e, index)}
            />
          )
        })}
      </div>
    </div>
  )
}
