import { useEffect, useId, useRef, useState } from 'react'

// APG select-only combobox pattern: a button opens a listbox of sizes.
// The listbox exists only while open, and sold-out sizes cannot be chosen.
export default function SizePicker({ sizes, value, onChange, error, buttonRef, describedBy }) {
  const labelId = useId()
  const valueId = useId()
  const listId = useId()
  const wrapRef = useRef(null)
  const optionRefs = useRef([])
  const [open, setOpen] = useState(false)
  const [active, setActive] = useState(0)

  const chosen = sizes.find((s) => s.us === value)
  const label = chosen ? `US ${chosen.us} · EU ${chosen.eu}` : 'Select'

  function openList() {
    const idx = chosen ? sizes.indexOf(chosen) : sizes.findIndex((s) => !s.soldOut)
    setActive(Math.max(idx, 0))
    setOpen(true)
  }

  function closeList(returnFocus) {
    setOpen(false)
    if (returnFocus) buttonRef.current?.focus()
  }

  function choose(index) {
    const size = sizes[index]
    if (size.soldOut) return
    onChange(size.us)
    closeList(true)
  }

  // Move focus into the listbox when it opens.
  useEffect(() => {
    if (open) optionRefs.current[active]?.focus()
  }, [open, active])

  // Close when the pointer is pressed outside the control.
  useEffect(() => {
    if (!open) return
    function onPointerDown(e) {
      if (!wrapRef.current?.contains(e.target)) setOpen(false)
    }
    document.addEventListener('pointerdown', onPointerDown)
    return () => document.removeEventListener('pointerdown', onPointerDown)
  }, [open])

  function onListKeyDown(e) {
    const last = sizes.length - 1
    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault()
        setActive((i) => Math.min(i + 1, last))
        break
      case 'ArrowUp':
        e.preventDefault()
        setActive((i) => Math.max(i - 1, 0))
        break
      case 'Home':
        e.preventDefault()
        setActive(0)
        break
      case 'End':
        e.preventDefault()
        setActive(last)
        break
      case 'Enter':
      case ' ':
        e.preventDefault()
        choose(active)
        break
      case 'Escape':
        e.preventDefault()
        closeList(true)
        break
      default:
        break
    }
  }

  return (
    <div
      className="size-picker"
      ref={wrapRef}
      onBlur={(e) => {
        if (!wrapRef.current.contains(e.relatedTarget)) setOpen(false)
      }}
    >
      <button
        ref={buttonRef}
        type="button"
        className={`size-picker__button${error ? ' is-invalid' : ''}`}
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-controls={open ? listId : undefined}
