import { createPortal } from 'react-dom'
import { useEffect, useId, useRef, useState } from 'react'
import { SIZE_CHART } from '../data/product.js'

const FOCUSABLE =
  'a[href], button:not([disabled]), input:not([disabled]), [tabindex]:not([tabindex="-1"])'

function recommend(footCm, unit) {
  const row = SIZE_CHART.find((r) => footCm <= r.maxCm)
  if (!row) return null
  return unit === 'EU' ? `EU ${row.eu}` : `US ${row.us}`
}

// Modal dialog (APG pattern): focus moves inside, Tab stays inside, Escape
// closes it, the page behind is made inert, and focus returns to the trigger.
export default function SizeGuideDialog({ onClose, returnFocusRef }) {
  const titleId = useId()
  const footId = useId()
  const hintId = useId()
  const errorId = useId()
  const dialogRef = useRef(null)
  const [foot, setFoot] = useState('')
  const [unit, setUnit] = useState('US')

  const footCm = Number(foot)
  const footValid = foot !== '' && footCm >= 20 && footCm <= 35
  const footInvalid = foot !== '' && !footValid
  const result = footValid ? recommend(footCm, unit) : null

  useEffect(() => {
    const root = document.getElementById('root')
    root.inert = true
    dialogRef.current?.querySelector('input')?.focus()
    return () => {
      root.inert = false
      returnFocusRef.current?.focus()
    }
  }, [returnFocusRef])

  function onKeyDown(e) {
    if (e.key === 'Escape') {
      e.preventDefault()
      onClose()
      return
    }
    if (e.key !== 'Tab') return
    const items = [...dialogRef.current.querySelectorAll(FOCUSABLE)]
    if (items.length === 0) return
    const first = items[0]
    const last = items[items.length - 1]
    if (e.shiftKey && document.activeElement === first) {
      e.preventDefault()
      last.focus()
    } else if (!e.shiftKey && document.activeElement === last) {
      e.preventDefault()
      first.focus()
    }
  }

  return createPortal(
    <div className="dialog-backdrop">
      <div
        ref={dialogRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby={titleId}
        className="dialog"
        onKeyDown={onKeyDown}
      >
        <div className="dialog__header">
          <h2 id={titleId}>Size guide</h2>
          <button type="button" className="icon-button" aria-label="Close size guide" onClick={onClose}>
            <span aria-hidden="true">×</span>
          </button>
        </div>

        <table className="size-table">
          <caption>Trail Runner 2 size chart</caption>
          <thead>
            <tr>
              <th scope="col">US</th>
              <th scope="col">EU</th>
              <th scope="col">Max. foot (cm)</th>
            </tr>
          </thead>
          <tbody>
            {SIZE_CHART.map((row) => (
              <tr key={row.us}>
                <td>{row.us}</td>
                <td>{row.eu}</td>
                <td>{row.maxCm.toFixed(1)}</td>
              </tr>
            ))}
          </tbody>
        </table>

        <div className="dialog__form">
          <div className="field">
            <label htmlFor={footId}>Foot length (cm)</label>
            <input
              id={footId}
              type="number"
              inputMode="decimal"
              step="0.1"
              min="20"
              max="35"
              value={foot}
              onChange={(e) => setFoot(e.target.value)}
              aria-describedby={footInvalid ? `${hintId} ${errorId}` : hintId}
              aria-invalid={footInvalid || undefined}
            />
            <p id={hintId} className="field__hint">
              Measure from heel to longest toe while standing.
            </p>
            {footInvalid && (
              <p id={errorId} className="field__error">
                Enter a value between 20 and 35 cm.
              </p>
            )}
          </div>

          <fieldset className="field">
            <legend>Show my size in</legend>
            <label className="inline-choice">
              <input type="radio" name={`${footId}-unit`} value="US" checked={unit === 'US'} onChange={() => setUnit('US')} />
              US
            </label>
            <label className="inline-choice">
              <input type="radio" name={`${footId}-unit`} value="EU" checked={unit === 'EU'} onChange={() => setUnit('EU')} />
              EU
            </label>
          </fieldset>

          <div className="dialog__result" role="status">
            {result ? (
              <p className="dialog__recommendation">Your size: {result}</p>
            ) : footValid ? (
              <p>Our largest size is shorter than this foot. Please contact us for help.</p>
            ) : (
              <p>Enter your length above to get a recommendation.</p>
            )}
          </div>
        </div>
      </div>
    </div>,
    document.body,
  )
}
