import { useId, useRef, useState } from 'react'
import { DETAILS, PRODUCT, REVIEWS, SHIPPING } from '../data/product.js'

// APG tabs pattern with automatic activation. Arrow keys, Home and End move
// between tabs; Tab moves into the selected panel.
export default function MoreInfoTabs() {
  const baseId = useId()
  const tabRefs = useRef([])
  const [selected, setSelected] = useState(0)

  const tabs = [
    {
      label: 'Details',
      content: (
        <dl className="spec-list">
          {DETAILS.map(([term, value]) => (
            <div key={term}>
              <dt>{term}</dt>
              <dd>{value}</dd>
            </div>
          ))}
        </dl>
      ),
    },
    {
      label: 'Reviews',
      content: (
        <div>
          <p>
            Rated {PRODUCT.rating} out of 5 from {PRODUCT.reviewCount} reviews.
          </p>
          <ul className="review-list">
            {REVIEWS.map((review) => (
              <li key={review.author}>
                <p>
                  <strong>{review.author}</strong>, {review.rating} out of 5
                </p>
                <p>{review.text}</p>
              </li>
            ))}
          </ul>
        </div>
      ),
    },
    {
      label: 'Shipping',
      content: (
        <ul className="plain-list">
          {SHIPPING.map((line) => (
            <li key={line}>{line}</li>
          ))}
        </ul>
      ),
    },
  ]

  function select(index) {
    setSelected(index)
    tabRefs.current[index]?.focus()
  }

  function onKeyDown(e, index) {
    const last = tabs.length - 1
    let next = null
    if (e.key === 'ArrowRight') next = index === last ? 0 : index + 1
    if (e.key === 'ArrowLeft') next = index === 0 ? last : index - 1
    if (e.key === 'Home') next = 0
    if (e.key === 'End') next = last
    if (next !== null) {
      e.preventDefault()
      select(next)
    }
  }

  return (
    <section className="more-info" aria-labelledby={`${baseId}-heading`}>
      <h2 id={`${baseId}-heading`}>More information</h2>
      <div role="tablist" aria-label="More information" className="tablist">
        {tabs.map((tab, index) => (
          <button
            key={tab.label}
            ref={(el) => (tabRefs.current[index] = el)}
            type="button"
            role="tab"
            id={`${baseId}-tab-${index}`}
            aria-selected={selected === index}
            aria-controls={`${baseId}-panel-${index}`}
            tabIndex={selected === index ? 0 : -1}
            className="tab"
            onClick={() => select(index)}
            onKeyDown={(e) => onKeyDown(e, index)}
          >
            {tab.label}
          </button>
        ))}
      </div>
      {tabs.map((tab, index) => (
        <div
          key={tab.label}
          role="tabpanel"
          id={`${baseId}-panel-${index}`}
          aria-labelledby={`${baseId}-tab-${index}`}
          tabIndex={0}
          hidden={selected !== index}
          className="tabpanel"
        >
          {tab.content}
        </div>
      ))}
    </section>
  )
}
