import { useId, useState } from 'react'

export const MIN_QTY = 1
export const MAX_QTY = 10

const clamp = (n) => Math.min(MAX_QTY, Math.max(MIN_QTY, n))

// Quantity typed in the box, or changed one at a time with the buttons.
export default function QuantityField({ value, onChange }) {
  const id = useId()
  const [text, setText] = useState(String(value))

  // Keep the typed text in step when the value changes from the buttons.
  if (Number(text) !== value && !(text === '' && value === MIN_QTY)) {
    setText(String(value))
  }

  function commit(next) {
    onChange(next)
    setText(String(next))
  }

  return (
    <div className="quantity">
      <label htmlFor={id} className="quantity__label">Quantity</label>
      <div className="quantity__control">
        <button
          type="button"
          className="stepper"
          aria-label="Decrease quantity"
          disabled={value <= MIN_QTY}
          onClick={() => commit(clamp(value - 1))}
        >
          <span aria-hidden="true">−</span>
        </button>
        <input
          id={id}
          type="number"
          inputMode="numeric"
          min={MIN_QTY}
          max={MAX_QTY}
          step={1}
          value={text}
          onChange={(e) => {
            const raw = e.target.value
            setText(raw)
            const n = parseInt(raw, 10)
            if (Number.isFinite(n)) onChange(clamp(n))
          }}
          onBlur={() => commit(clamp(parseInt(text, 10) || MIN_QTY))}
        />
        <button
          type="button"
          className="stepper"
          aria-label="Increase quantity"
          disabled={value >= MAX_QTY}
          onClick={() => commit(clamp(value + 1))}
        >
          <span aria-hidden="true">+</span>
        </button>
      </div>
    </div>
  )
}
