import { useEffect, useId, useState } from 'react'

// A small "i" button that explains the price. The explanation appears on
// hover or keyboard focus, can be dismissed with Escape (from anywhere on the
// page), and stays open while the pointer is over it.
export default function PriceInfo({ text }) {
  const tipId = useId()
  const [hovered, setHovered] = useState(false)
  const [focused, setFocused] = useState(false)
  const [dismissed, setDismissed] = useState(false)
  const open = (hovered || focused) && !dismissed

  useEffect(() => {
    if (!open) return
    function onKeyDown(e) {
      if (e.key === 'Escape') setDismissed(true)
    }
    document.addEventListener('keydown', onKeyDown)
    return () => document.removeEventListener('keydown', onKeyDown)
  }, [open])

  return (
    <span
      className="price-info"
      onMouseEnter={() => {
        setHovered(true)
        setDismissed(false)
      }}
      onMouseLeave={() => setHovered(false)}
    >
      <button
        type="button"
        className="price-info__button"
        aria-label="Price information"
        aria-describedby={open ? tipId : undefined}
        onFocus={() => {
          setFocused(true)
          setDismissed(false)
        }}
        onBlur={() => setFocused(false)}
      >
        i
      </button>
      {open && (
        <span role="tooltip" id={tipId} className="price-info__tip">
          {text}
        </span>
      )}
    </span>
  )
}
