import { StrictMode } from 'react'
import { flushSync } from 'react-dom'
import { createRoot } from 'react-dom/client'
import HomePage from './pages/HomePage.jsx'
import ProductPage from './pages/ProductPage.jsx'
import './styles.css'

const pages = {
  '/': HomePage,
  '/products/trail-runner-2': ProductPage,
}

const Page = pages[window.location.pathname] ?? (() => <p>Page not found.</p>)

// Commit the first render synchronously so the page is in the DOM (and has
// focusable content) by the time the browser fires the load event.
const root = createRoot(document.getElementById('root'))
flushSync(() => {
  root.render(
    <StrictMode>
      <Page />
    </StrictMode>,
  )
})
